`)}const nn=[{id:"leistungsdiagnostik",name:"Leistungsdiagnostik",title:"Leistungsdiagnostik und Leistungsbewertung",custom:!0,sections:[{paragraph:"Die drei Arten der Leistungsdiagnostik bzw. Leistungsbewertung werden nach dem Zeitpunkt und Zweck der Bewertung unterschieden."},{columns:["Art","Wann?","Wozu?","Beispiel"],rows:[["Diagnostisch","Vor dem Lernen","Vorwissen und Lernstand feststellen","Eingangstest"],["Formativ","Während des Lernens","Lernfortschritt erkennen und fördern","Feedback zu einem Entwurf"],["Summativ","Nach dem Lernen","Lernergebnis abschließend bewerten","Benotete Klassenarbeit"]]},{heading:"Merksatz",items:[{prefix:"Diagnostisch:",text:"Wo stehen die Schüler?"},{prefix:"Formativ:",text:"Wie können sie sich verbessern?"},{prefix:"Summativ:",text:"Was haben sie gelernt?"}]},{paragraph:"Die Unterscheidung hilft Lehrkräften, Lernstände zu erkennen, den Unterricht anzupassen und Leistungen am Ende zu bewerten."}],summary:"Die drei Arten der Leistungsdiagnostik bzw. Leistungsbewertung unterscheiden sich nach Zeitpunkt und Zweck: Diagnostisch vor dem Lernen – Vorwissen und Lernstand feststellen, z. B. Eingangstest. Formativ während des Lernens – Lernfortschritt erkennen und fördern, z. B. Feedback zu einem Entwurf. Summativ nach dem Lernen – Lernergebnis abschließend bewerten, z. B. benotete Klassenarbeit. Merksatz: Diagnostisch: Wo stehen die Schüler? Formativ: Wie können sie sich verbessern? Summativ: Was haben sie gelernt? Die Unterscheidung hilft Lehrkräften, Lernstände zu erkennen, den Unterricht anzupassen und Leistungen am Ende zu bewerten.",application:"Berücksichtige bei der Unterrichtsplanung passende diagnostische, formative und summative Möglichkeiten entsprechend Lernziel und Unterrichtsphase."},{id:"sprachliche-vereinfachung",name:"Sprachliche Vereinfachung",title:"Sprachliche Vereinfachung",custom:!0,sections:rt,summary:Ue("Sprachliche Vereinfachung",rt),application:"Berücksichtige diese vom Nutzer hinterlegten Maßnahmen zur Textoptimierung und ihren Einsatz im Unterricht bei der Planung und Prüfung."},{id:"lehrervortrag",name:"Lehrervortrag",href:"/pruefungen/paedagogik-quellen/d25-grundkurs-1-unterrichtsplanung-skript.pdf#page=17",source:"public/material/unterrichtsbaukasten/unterrichtsplanung.txt",original:"public/pruefungen/paedagogik-quellen/d25-grundkurs-1-unterrichtsplanung-skript.pdf",pages:"17–18 und 25",title:"1. Lehrervortrag",custom:!0,sections:Yn,summary:Ue("1. Lehrervortrag",Yn),application:"Berücksichtige diese vom Nutzer hinterlegten Hinweise zum Lehrervortrag bei der Planung und Prüfung."},{id:"fragend-entwickelnd",name:"Fragend-entwickelnd",href:"/pruefungen/paedagogik-quellen/d25-grundkurs-1-unterrichtsplanung-skript.pdf#page=20",source:"public/material/unterrichtsbaukasten/unterrichtsplanung.txt",original:"public/pruefungen/paedagogik-quellen/d25-grundkurs-1-unterrichtsplanung-skript.pdf",pages:"17 und 20–21",title:"2. Fragend-entwickelnder Unterricht",custom:!0,sections:_n,summary:Ue("2. Fragend-entwickelnder Unterricht",_n),application:"Berücksichtige diese vom Nutzer hinterlegten Hinweise zum fragend-entwickelnden Unterricht bei der Planung und Prüfung."},{id:"gute-arbeitsauftraege",name:"Gute Arbeitsaufträge",title:"Arbeitsaufträge – worauf muss ich achten?",custom:!0,sections:et,summary:Ue("Arbeitsaufträge – worauf muss ich achten?",et),application:"Berücksichtige diese neun Kriterien bei der Formulierung und Prüfung der Arbeitsaufträge im Unterrichtsentwurf."},{id:"spannungskurve",name:"Spannungskurve",title:"Spannungskurve (Dramaturgie)",custom:!0,sections:nt,summary:Ue("Spannungskurve (Dramaturgie)",nt),application:"Berücksichtige diese vom Nutzer hinterlegte Dramaturgie mit fünf Phasen und die Umsetzungstipps bei der Planung und Prüfung des Unterrichts."},{id:"klare-phasentrennung",name:"Klare Phasentrennung und sichtbare Markierung",title:"Klare Phasentrennung und sichtbare Markierung",custom:!0,sections:tt,summary:Ue("Klare Phasentrennung und sichtbare Markierung",tt),application:"Berücksichtige diese vom Nutzer hinterlegten Hinweise zu klaren Phasen, deutlichen Übergängen und räumlichen, akustischen, visuellen sowie verbalen Markierungen bei der Planung und Prüfung."},{id:"lernzieldimensionen",name:"Lernzieldimensionen",title:"Lernzieldimensionen",custom:!0,sections:it,summary:Ue("Lernzieldimensionen",it),application:"Berücksichtige die ausgewählten Lernzieldimensionen bei der Planung und Prüfung."}];function os(n){return n.custom?`
